#include <algorithm>
#include <string>
#include <vector>

static void combine(const std::vector<int>& nums, std::size_t start, int remaining, std::vector<int>& chosen, std::vector<std::vector<int>>& out)
{
    if (remaining == 0) { out.push_back(chosen); return; }
    for (std::size_t i = start; i < nums.size() && nums[i] <= remaining; ++i)
    {
        chosen.push_back(nums[i]);
        combine(nums, i + 1, remaining - nums[i], chosen, out);
        chosen.pop_back();
    }
}

std::vector<std::vector<int>> combinationsSumming(std::vector<int> numbers, int target)
{
    std::sort(numbers.begin(), numbers.end());
    std::vector<std::vector<int>> out;
    std::vector<int> chosen;
    combine(numbers, 0, target, chosen, out);
    return out;                                         // generated in lexicographic order already
}

static void permute(const std::vector<int>& nums, std::vector<bool>& used, std::vector<int>& current, std::vector<std::vector<int>>& out)
{
    if (current.size() == nums.size()) { out.push_back(current); return; }
    for (std::size_t i = 0; i < nums.size(); ++i)
    {
        if (used[i]) continue;
        if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;   // the same value in the same position again
        used[i] = true;
        current.push_back(nums[i]);
        permute(nums, used, current, out);
        current.pop_back();
        used[i] = false;
    }
}

std::vector<std::vector<int>> uniquePermutations(std::vector<int> numbers)
{
    std::sort(numbers.begin(), numbers.end());
    std::vector<std::vector<int>> out;
    std::vector<bool> used(numbers.size(), false);
    std::vector<int> current;
    permute(numbers, used, current, out);
    return out;
}

static long long queens(int row, int n, std::vector<bool>& col, std::vector<bool>& d1, std::vector<bool>& d2)
{
    if (row == n) return 1;
    long long total = 0;
    for (int c = 0; c < n; ++c)
    {
        if (col[c] || d1[row + c] || d2[row - c + n - 1]) continue;
        col[c] = d1[row + c] = d2[row - c + n - 1] = true;
        total += queens(row + 1, n, col, d1, d2);
        col[c] = d1[row + c] = d2[row - c + n - 1] = false;
    }
    return total;
}

long long countQueens(int n)
{
    if (n <= 0) return 0;
    std::vector<bool> col(n, false), d1(2 * n, false), d2(2 * n, false);
    return queens(0, n, col, d1, d2);
}

