struct Sudoku
{
    std::vector<std::string>& b;
    int rows[9] = {}, cols[9] = {}, boxes[9] = {};          // bit d set: digit d + 1 is used

    explicit Sudoku(std::vector<std::string>& board) : b(board) {}

    bool load()
    {
        for (int r = 0; r < 9; ++r)
            for (int c = 0; c < 9; ++c)
            {
                if (b[r][c] == '.') continue;
                int bit = 1 << (b[r][c] - '1');
                int box = r / 3 * 3 + c / 3;
                if ((rows[r] | cols[c] | boxes[box]) & bit) return false;    // the givens already clash
                rows[r] |= bit; cols[c] |= bit; boxes[box] |= bit;
            }
        return true;
    }

    bool solve()
    {
        int bestR = -1, bestC = -1, bestCount = 10, bestMask = 0;
        for (int r = 0; r < 9; ++r)
            for (int c = 0; c < 9; ++c)
            {
                if (b[r][c] != '.') continue;
                int mask = ~(rows[r] | cols[c] | boxes[r / 3 * 3 + c / 3]) & 0x1FF;
                int count = 0;
                for (int m = mask; m; m &= m - 1) ++count;
                if (count < bestCount) { bestR = r; bestC = c; bestCount = count; bestMask = mask; }
            }
        if (bestR == -1) return true;                       // no empty cell left
        int box = bestR / 3 * 3 + bestC / 3;
        for (int d = 0; d < 9; ++d)
        {
            int bit = 1 << d;
            if (!(bestMask & bit)) continue;
            b[bestR][bestC] = static_cast<char>('1' + d);
            rows[bestR] |= bit; cols[bestC] |= bit; boxes[box] |= bit;
            if (solve()) return true;
            rows[bestR] &= ~bit; cols[bestC] &= ~bit; boxes[box] &= ~bit;
        }
        b[bestR][bestC] = '.';
        return false;
    }
};
}

bool solveSudoku(std::vector<std::string>& board)
{
    Sudoku s(board);
    return s.load() && s.solve();
}

